def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    # Begin by cooperating to establish mutual cooperation.
    if n <= 3:
        return 'C'

    total_opp_def = sum(1 for a, b in history if b == 'D')
    total_my_def = sum(1 for a, b in history if a == 'D')

    # If opponent has never defected, keep cooperating, except a final defection.
    if total_opp_def == 0:
        if n >= 100:
            return 'D'
        return 'C'

    # Detect sustained or frequently-defecting opponents early.
    if n >= 5:
        opp_recent5 = history[-5:]
        opp_def_rec5 = sum(1 for a, b in opp_recent5 if b == 'D')
        if opp_def_rec5 >= 4:
            return 'D'
        if opp_def_rec5 == 5:
            return 'D'

    # Strong punishment for immediate, repeated defection.
    if opp_last == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        # Single recent defection: retaliate unless opponent is otherwise clean,
        # in which case offer limited forgiveness.
        if total_opp_def <= 1:
            # If we've ever defected, mirror by cooperating; otherwise retaliate once.
            if total_my_def == 0:
                return 'D'
            return 'C'
        # Opponent defects sometimes. Retaliate, but allow forgiveness if
        # opponent has been mostly cooperative overall.
        if total_opp_def * 3 <= n and total_my_def > 0:
            # Forgive to avoid DD traps when our own hand isn't clean.
            if rng.random() < 0.5:
                return 'C'
        return 'D'

    # Opponent cooperated last round.
    # Avoid excessive exploitation: if we have been defecting a lot and the
    # opponent remains cooperative, return to cooperation to rebuild mutual gain.
    if total_my_def > 0 and total_my_def * 2 >= total_opp_def + 2:
        return 'C'

    # If opponent has shown moderate defection, defect occasionally to test.
    if n >= 10 and total_opp_def * 5 >= n:
        if rng.random() < 0.15:
            return 'D'

    # Last-round exploitation if opponent has been very cooperative.
    if n >= 99:
        if total_opp_def <= 2:
            return 'D'
        return 'C'

    # Near the end, exploit a strongly-cooperative opponent.
    if n >= 90 and total_opp_def <= 2:
        return 'D'

    return 'C'
